func findMedianSortedArrays(_ nums1: [Int], _ nums2: [Int]) -> Double {
    let (a, b) = nums1.count <= nums2.count ? (nums1, nums2) : (nums2, nums1)
    let m = a.count, n = b.count, half = (m + n + 1) / 2
    var lo = 0, hi = m
    while lo <= hi {
        let i = (lo + hi) / 2, j = half - i
        let aLeft = i == 0 ? Int.min : a[i - 1], aRight = i == m ? Int.max : a[i]
        let bLeft = j == 0 ? Int.min : b[j - 1], bRight = j == n ? Int.max : b[j]
        if aLeft <= bRight && bLeft <= aRight {
            if (m + n) % 2 == 1 { return Double(max(aLeft, bLeft)) }
            return Double(max(aLeft, bLeft) + min(aRight, bRight)) / 2
        }
        if aLeft > bRight { hi = i - 1 } else { lo = i + 1 }
    }
    return 0
}
